<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import { Plus, RefreshCw, Server, Trash2, X, Users, RadioTower, Activity, Power, Settings2, Search, CheckCircle2, TriangleAlert, ArrowUpRight, CircleCheck, Network } from 'lucide-vue-next';
import { useApi, isCancelled } from '../lib/api';
import { latestRequest, serialPoll } from '../lib/requests';
import { usePanelContext } from '../composables/panelContext';
import { useModalFocus } from '../composables/useModalFocus';
import SubsiteNodePool from '../components/SubsiteNodePool.vue';
import ManagedSitePolicy from '../components/ManagedSitePolicy.vue';
import { siteState, type ManagedSite } from '../lib/sites';
import { t } from '../i18n';
const api=useApi('/business-sites');
const {state,selectedSite,switchSite,go,bytes}=usePanelContext();
const settling=ref<ManagedSite[]>([]);
const sites=ref<ManagedSite[]>([]),error=ref(''),loaded=ref(false),refreshing=ref(false),busy=ref(false),adding=ref(false);
const pooling=ref<ManagedSite|null>(null);
const removing=ref<ManagedSite|null>(null),editing=ref<ManagedSite|null>(null),controlling=ref<ManagedSite|null>(null);
const form=reactive({token:'',url:'',name:''});
const jobs=reactive<Record<string,boolean>>({});
const search=ref(''),filter=ref('all'),notice=ref(''),updatedAt=ref(0),openingSite=ref('');
const dialog=ref<HTMLElement|null>(null),modalOpen=computed(()=>adding.value||!!removing.value||!!controlling.value);
useModalFocus(modalOpen,dialog,close);
const isOnline=(s:ManagedSite)=>s.last_seen>Date.now()/1000-90&&!s.error;
const needsAttention=(s:ManagedSite)=>!!(s.error||s.mount?.error||s.connection?.status?.service_error||s.connection?.status?.pending)||!isOnline(s);
const attention=computed(()=>sites.value.filter(needsAttention).length);
const mountedCount=computed(()=>sites.value.reduce((total,s)=>total+(s.mount?.nodes.filter(n=>n.enabled).length||0),0));
const visibleSites=computed(()=>sites.value.filter(s=>[s.name,s.connection?.url,s.id].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())&&(filter.value==='all'||filter.value==='online'&&isOnline(s)||filter.value==='attention'&&needsAttention(s)||filter.value==='paused'&&s.connection?.status?.paused)));
const filters=computed(()=>[{id:'all',label:t('全部站点'),count:sites.value.length},{id:'online',label:t('在线站点'),count:online.value},{id:'attention',label:t('需要关注'),count:attention.value},{id:'paused',label:t('服务已暂停'),count:sites.value.filter(s=>s.connection?.status?.paused).length}]);
const budgetPercent=(s:ManagedSite)=>s.monthly_budget?Math.min(100,Math.round((s.monthly_usage||0)/s.monthly_budget*100)):0;
const liveAvailable=(s:ManagedSite)=>!!s.connection?.status?.live&&!s.error&&s.connection.status.sampled_at>Date.now()-15000;

const needsAddress=computed(()=>form.token.trim().startsWith('gyp_'));
const online=computed(()=>sites.value.filter(s=>s.last_seen>Date.now()/1000-90&&!s.error).length);
const direct=computed(()=>sites.value.filter(s=>s.connection));
const changing=computed(()=>busy.value||adding.value||!!removing.value||!!editing.value||!!controlling.value||!!pooling.value);
let disposed=false,directoryRevision=0;
const directoryRequest=latestRequest();
function replace(site:ManagedSite){const i=sites.value.findIndex(s=>s.id===site.id);if(i>=0)sites.value[i]=site;}
async function probe(site:ManagedSite){
 if(jobs[site.id])return;jobs[site.id]=true;const revision=directoryRevision;
 try{const updated=await api<ManagedSite>('/'+site.id+'/probe','POST',{});if(revision===directoryRevision)replace(updated);}
 catch(e){if(!isCancelled(e)&&!disposed&&revision===directoryRevision){const current=sites.value.find(s=>s.id===site.id);if(current)current.error=(e as Error).message;}}
 finally{delete jobs[site.id];}
}
async function load(probeAll=false){
 const request=directoryRequest.start();refreshing.value=true;const revision=directoryRevision;
 try{const out=await api<{sites:ManagedSite[];settling?:ManagedSite[]}>('','GET',undefined,{signal:request.signal});if(!directoryRequest.isCurrent(request)||revision!==directoryRevision)return;sites.value=out.sites;settling.value=out.settling||[];loaded.value=true;error.value='';
  if(probeAll){const queue=[...direct.value];await Promise.all(Array.from({length:Math.min(4,queue.length)},async()=>{while(queue.length&&!disposed&&directoryRequest.isCurrent(request)&&revision===directoryRevision){const site=queue.shift();if(site)await probe(site);}}));}
  if(directoryRequest.isCurrent(request)&&revision===directoryRevision)updatedAt.value=Date.now();
 }catch(e){if(directoryRequest.isCurrent(request)&&revision===directoryRevision&&!isCancelled(e))error.value=(e as Error).message;}finally{if(directoryRequest.isCurrent(request))refreshing.value=false;}
}
function close(){if(busy.value)return;adding.value=false;removing.value=null;controlling.value=null;form.token='';error.value='';}
async function connect(){directoryRevision++;busy.value=true;error.value='';try{
 const site=await api<ManagedSite>('/import','POST',form);form.token='';form.url='';form.name='';adding.value=false;
 sites.value=sites.value.filter(s=>s.id!==site.id);sites.value.push(site);notice.value=t('子站已连接，可开始挂载节点。');await probe(site);
}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(){if(!removing.value)return;directoryRevision++;busy.value=true;error.value='';try{
 const id=removing.value.id;await api('/'+id,'DELETE',{});sites.value=sites.value.filter(s=>s.id!==id);removing.value=null;notice.value=t('子站已移除');
}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function control(){if(!controlling.value)return;directoryRevision++;busy.value=true;error.value='';try{
 const s=controlling.value;replace(await api<ManagedSite>('/'+s.id+'/control','POST',{paused:!s.connection?.status?.paused}));controlling.value=null;notice.value=t('服务调度已完成');
}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function manage(site:ManagedSite,page:string){if(openingSite.value)return;openingSite.value=site.id;try{await switchSite(site.id,site.name);if(selectedSite.value===site.id)go(page);}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{openingSite.value='';}}
function onPoolSaved(site:ManagedSite){directoryRevision++;replace(site);pooling.value=site;}
async function onPolicySaved(){directoryRevision++;await load();}
const poll=serialPoll(async()=>{if(!document.hidden&&!changing.value)await load(true);},()=>15000);
onMounted(()=>{void load(true);poll.start();});
onUnmounted(()=>{disposed=true;directoryRequest.cancel();poll.stop();form.token='';});
</script>
<template>
 <div class="subsite-page">
  <header class="page-heading"><div><div class="eyebrow">CONNECTED SITES</div><h1>{{t('子站管理与调度')}}</h1><p class="section-subtitle">{{t('集中连接、挂载与监控，每个子站仍可独立运营。')}}</p></div><div class="heading-actions"><button :disabled="refreshing||busy" @click="load(true)"><RefreshCw :size="16" :class="{spin:refreshing}"/>{{t(refreshing?'刷新中…':'刷新')}}</button><button class="primary" :disabled="busy" @click="adding=true;error='' "><Plus :size="16"/>{{t('导入子站令牌')}}</button></div></header>
  <div class="site-summary"><article><span class="summary-icon"><Server :size="19"/></span><div><span>{{t('已连接子站')}}</span><strong>{{loaded?sites.length:'—'}}<small>/ 64</small></strong></div></article><article><span class="summary-icon"><CircleCheck :size="19"/></span><div><span>{{t('在线站点')}}</span><strong>{{loaded?online:'—'}}</strong></div></article><article><span class="summary-icon" :class="{warning:attention}"><TriangleAlert :size="19"/></span><div><span>{{t('需要关注')}}</span><strong>{{loaded?attention:'—'}}</strong></div></article><article><span class="summary-icon"><Network :size="19"/></span><div><span>{{t('已启用挂载节点')}}</span><strong>{{loaded?mountedCount:'—'}}</strong></div></article></div>
  <p v-if="notice" class="site-notice" role="status"><CheckCircle2 :size="17"/><span>{{notice}}</span><button class="icon" :aria-label="t('关闭')" @click="notice=''"><X :size="16"/></button></p>
  <p v-if="error&&!modalOpen" class="error" role="alert">{{t(error)}}</p>
  <section class="site-directory" :aria-busy="refreshing">
   <div class="directory-toolbar"><div class="site-filters" role="group" :aria-label="t('筛选站点')"><button v-for="f in filters" :key="f.id" :aria-pressed="filter===f.id" @click="filter=f.id">{{f.label}}<span>{{f.count}}</span></button></div><div class="search"><Search :size="16"/><input v-model="search" :placeholder="t('搜索子站名称或地址')" :aria-label="t('搜索子站名称或地址')"/></div></div>
   <div class="directory-caption"><span>{{t('主站')}} · {{state?.system.site_id}}</span><span>{{t('每 15 秒自动刷新')}}<template v-if="updatedAt"> · {{new Date(updatedAt).toLocaleTimeString()}}</template></span></div>
   <div class="site-cards">
    <article v-for="s in visibleSites" :key="s.id" class="site-card" :class="{'has-issue':needsAttention(s)}">
     <header><span class="site-emblem"><Server :size="21"/></span><div class="site-identity"><h2>{{s.name}}</h2><p>{{s.connection?.url||s.info?.vless_host||s.id}}</p></div><span :class="['badge',needsAttention(s)?'warning':s.connection?.status?.paused?'neutral':'success']"><RefreshCw v-if="jobs[s.id]" :size="12" class="spin"/>{{t(jobs[s.id]?'检测中…':siteState(s))}}</span></header>
     <div class="site-meta"><span v-if="s.connection?.status">{{s.connection.status.edition.toUpperCase()}} · v{{s.connection.status.version}}</span><span v-else>{{t('子站')}}</span><span>{{t('上次连接')}} {{s.last_seen?new Date(s.last_seen*1000).toLocaleString():'—'}}</span></div>
     <div v-if="s.error||s.connection?.status?.service_error||s.mount?.error" class="site-error" role="status"><TriangleAlert :size="16"/><span>{{t(s.error||s.connection?.status?.service_error||s.mount?.error||'')}}</span></div>
     <div class="site-metrics"><div><span>{{t('用户')}}</span><strong>{{s.connection?.status?.control?s.connection.status.users:!s.connection?s.grants.length:'—'}}</strong><small>{{t('在线用户')}} {{s.connection?.status?.control&&liveAvailable(s)?(s.connection.status.online_users??'—'):'—'}}</small></div><div><span>{{t('节点')}}</span><strong>{{s.connection?.status?.control?s.connection.status.nodes:!s.connection?s.nodes.length+2:'—'}}</strong><small>{{s.mount?.nodes.length||0}} {{t('个已挂载')}}</small></div><div><span>{{t('实时流量')}}</span><strong class="rate">↓ {{liveAvailable(s)&&s.connection?.status?.live.download_rate!=null?bytes(s.connection.status.live.download_rate)+'/s':'—'}}</strong><small>↑ {{liveAvailable(s)&&s.connection?.status?.live.upload_rate!=null?bytes(s.connection.status.live.upload_rate)+'/s':'—'}}</small></div></div>
     <div v-if="s.monthly_budget" class="site-budget"><div><span>{{t('共享资源预算')}}</span><strong>{{bytes(s.monthly_usage||0)}} / {{bytes(s.monthly_budget)}}</strong></div><progress :value="budgetPercent(s)" max="100" :aria-label="t('共享资源预算')"/><small v-if="s.budget_cooldown_until&&s.budget_cooldown_until>Date.now()/1000">{{t('冷却中，预计')}} {{new Date(s.budget_cooldown_until*1000).toLocaleString()}} {{t('恢复')}}</small></div>
     <div v-if="s.connection?.status?.control" class="site-total"><span>{{t('累计流量')}}</span><strong>{{bytes(s.connection.status.upload+s.connection.status.download)}}</strong></div>
     <footer><div class="site-primary-actions" v-if="s.connection"><button v-if="s.connection.scope==='manage'" class="mount-action" :disabled="busy" @click="pooling=s"><Network :size="15"/>{{t('挂载节点')}}<ArrowUpRight :size="14"/></button><button :disabled="busy||!!openingSite||s.connection.scope!=='manage'" @click="manage(s,'users')"><Users :size="15"/>{{t('用户')}}</button><button :disabled="busy||!!openingSite||s.connection.scope!=='manage'" @click="manage(s,'nodes')"><RadioTower :size="15"/>{{t('节点')}}</button><button :disabled="busy||!!openingSite||s.connection.scope!=='manage'" @click="manage(s,'monitor')"><Activity :size="15"/>{{t('监控')}}</button></div><div v-else class="site-primary-actions"><button @click="editing=s"><Settings2 :size="15"/>{{t('权限调度')}}</button></div><details class="site-extra"><summary>{{t('更多操作')}}</summary><div><button v-if="s.connection?.status?.control&&s.connection.scope==='manage'" :disabled="busy" @click="controlling=s;error='' "><Power :size="14"/>{{t(s.connection.status.paused?'恢复服务':'暂停服务')}}</button><button class="remove-site" :disabled="busy" @click="removing=s;error='' "><Trash2 :size="14"/>{{t('移除子站')}}</button></div></details></footer>
    </article>
   </div>
   <div v-if="!visibleSites.length" class="directory-empty" role="status"><Server :size="34"/><h2>{{t(!loaded?'加载中…':sites.length?'没有匹配的子站':'连接你的第一个子站')}}</h2><p>{{t(sites.length?'试试其他名称或筛选条件。':'在子站生成令牌，导入后即可统一管理用户、节点与流量。')}}</p><button v-if="loaded&&!sites.length" class="primary" @click="adding=true;error=''"><Plus :size="16"/>{{t('导入子站令牌')}}</button><button v-else-if="sites.length" @click="search='';filter='all'">{{t('清除筛选')}}</button></div>
  </section>
  <section v-if="settling.length" class="settling-sites"><h3>{{t('等待结算的已移除子站')}}</h3><p class="field-help">{{t('授权撤回并确认最终用量后释放预留额度；子站离线或令牌已撤销时继续保留账本。')}}</p><p v-for="s in settling" :key="s.id">{{s.name}} · {{t(s.mount?.error||'等待撤销与流量结算')}}</p></section>
  <SubsiteNodePool v-if="pooling" :site="pooling" @close="pooling=null" @saved="onPoolSaved"/>
  <ManagedSitePolicy v-if="editing" :site="editing" @close="editing=null" @saved="onPolicySaved"/>
  <Teleport to="body"><div v-if="adding||removing||controlling" class="message-overlay" @click.self="close">
   <form v-if="adding" ref="dialog" tabindex="-1" class="compose-card" role="dialog" aria-modal="true" :aria-label="t('导入子站令牌')" @submit.prevent="connect">
    <header><h2>{{t('导入子站令牌')}}</h2><button type="button" class="icon" :disabled="busy" :aria-label="t('关闭')" @click="close"><X/></button></header>
    <p>{{t('在子站的“配对令牌”页面生成管理令牌，复制完整内容粘贴到这里。')}}</p>
    <label>{{t('子站令牌')}}<textarea v-model="form.token" rows="4" maxlength="8192" autocomplete="off" spellcheck="false" required/></label>
    <label v-if="needsAddress">{{t('子站 HTTPS 地址')}}<input v-model="form.url" type="url" placeholder="https://child.example.com" required/></label>
    <label>{{t('备注名称（选填）')}}<input v-model="form.name" maxlength="64"/></label>
    <p class="field-help">{{t('新令牌自带地址，旧 gyp_ 令牌补填地址即可。重复导入同一站点会更新连接，不会新增重复记录。')}}</p>
    <p v-if="error" class="error" role="alert">{{t(error)}}</p><footer><button type="button" :disabled="busy" @click="close">{{t('取消')}}</button><button class="primary" :disabled="busy">{{t(busy?'正在连接…':'连接子站')}}</button></footer>
   </form>
   <section v-else-if="removing" ref="dialog" tabindex="-1" class="compose-card" role="alertdialog" aria-modal="true" :aria-label="t('移除子站')"><h2>{{t('移除子站')}} · {{removing.name}}</h2><p>{{t('移除后主站停止管理此站点，子站的软件、账号和数据保留。离线子站也可以移除，之后可重新导入令牌。')}}</p><p v-if="!removing.connection||removing.mount" class="field-help">{{t('移除后立即停止分发挂载节点，离线授权等待租约到期，未结算额度继续保留。')}}</p><p v-if="error" class="error" role="alert">{{t(error)}}</p><footer><button :disabled="busy" @click="close">{{t('取消')}}</button><button class="danger-button" :disabled="busy" @click="remove">{{t('确认移除')}}</button></footer></section>
   <section v-else-if="controlling" ref="dialog" tabindex="-1" class="compose-card" role="alertdialog" aria-modal="true" :aria-label="t('服务调度')"><h2>{{t(controlling.connection?.status?.paused?'恢复服务':'暂停服务')}} · {{controlling.name}}</h2><p>{{t('暂停会停止子站代理用户的访问；面板登录仍可用。恢复后按原有用户和节点权限提供服务。')}}</p><p v-if="error" class="error" role="alert">{{t(error)}}</p><footer><button :disabled="busy" @click="close">{{t('取消')}}</button><button class="primary" :disabled="busy" @click="control">{{t('确认')}}</button></footer></section>
  </div></Teleport>
 </div>
</template>
<style scoped>
