.site-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.site-card{background:var(--surface);border:1px solid var(--border);border-radius:18px;padding:22px;min-width:0;display:flex;flex-direction:column}.site-card.has-issue{border-color:color-mix(in srgb,var(--warning,#a56b1d) 35%,var(--border))}.site-card>header{display:flex;align-items:center;gap:12px}.site-identity{flex:1;min-width:0}.site-identity h2{font-size:16px;line-height:1.4;margin:0 0 4px;overflow-wrap:anywhere}.site-identity p{font-size:12px;color:var(--muted);margin:0;overflow-wrap:anywhere}.site-card .badge{display:inline-flex;gap:5px;align-items:center;flex-shrink:0}.site-meta{display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px;font-size:11px;color:var(--muted);margin:16px 0}.site-error{display:flex;align-items:flex-start;gap:8px;padding:11px 12px;border-radius:9px;background:var(--warning-soft,#ad751c0d);color:var(--warning,#a56b1d);font-size:12px;line-height:1.7;overflow-wrap:anywhere}.site-error svg{flex-shrink:0;margin-top:2px}.site-error span{min-width:0}.site-metrics{display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:12px;padding:18px 0}.site-metrics>div{display:flex;flex-direction:column;gap:8px;border-right:1px solid var(--border)}.site-metrics>div:last-child{border:0;padding-left:4px}.site-metrics span,.site-metrics small{font-size:11px;color:var(--muted)}.site-metrics strong{font-size:23px;font-variant-numeric:tabular-nums;line-height:1.2}.site-metrics strong.rate{font-size:17px;white-space:nowrap}.site-budget{padding:0 0 18px}.site-budget>div,.site-total{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;color:var(--muted)}.site-budget strong,.site-total strong{font-weight:500;color:var(--secondary)}.site-budget progress{appearance:none;display:block;border:0;border-radius:8px;background:var(--surface-raised);height:5px;width:100%;margin-top:9px;overflow:hidden}.site-budget progress::-webkit-progress-bar{background:var(--surface-raised)}.site-budget progress::-webkit-progress-value{background:var(--accent);border-radius:8px}.site-budget progress::-moz-progress-bar{background:var(--accent)}.site-budget small{display:block;margin-top:8px;font-size:11px;color:var(--warning,#a56b1d)}.site-total{padding:0 0 18px}.site-card footer{border-top:1px solid var(--border);padding-top:14px;margin-top:auto}.site-primary-actions{display:flex;gap:7px;flex-wrap:wrap}.site-primary-actions button{font-size:12px;min-height:44px;padding:8px 11px}.site-primary-actions .mount-action{color:var(--accent);background:var(--accent-soft);border-color:transparent;margin-right:auto}.site-extra{font-size:11px;color:var(--muted);margin-top:10px}.site-extra summary{cursor:pointer;min-height:32px;align-content:center;width:fit-content}.site-extra>div{display:flex;gap:8px;flex-wrap:wrap;margin-top:6px}.site-extra button{min-height:44px;font-size:12px}.remove-site{color:var(--danger)}.directory-empty{border:1px dashed var(--border);border-radius:18px;text-align:center;padding:56px 24px;background:var(--surface);display:flex;flex-direction:column;align-items:center;gap:14px}.directory-empty>svg{color:var(--accent)}.directory-empty h2{font-size:18px;margin:0}.directory-empty p{font-size:13px;line-height:1.7;color:var(--muted);max-width:380px;margin:0 0 5px}.settling-sites{padding:20px 22px;border:1px solid var(--border);border-radius:16px;background:var(--surface)}.settling-sites h3{font-size:14px;margin:0 0 8px}.settling-sites>p{font-size:12px;color:var(--secondary);line-height:1.7;overflow-wrap:anywhere}.compose-card textarea{width:100%;resize:vertical;font:inherit;overflow-wrap:anywhere}.compose-card{max-height:90dvh;overflow:auto}.compose-card footer button{min-height:44px}
@media(max-width:1150px){.site-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.site-cards{grid-template-columns:1fr}}@media(max-width:700px){.subsite-page{gap:18px}.heading-actions{width:100%;flex-wrap:wrap}.heading-actions .primary{flex:1}.site-summary{gap:10px}.site-summary article{padding:15px 12px;gap:10px}.summary-icon{width:34px;height:34px;border-radius:10px}.site-summary strong{font-size:25px}.site-summary article>div>span{font-size:11px}.directory-toolbar{gap:12px}.directory-toolbar .search{flex-basis:100%;width:100%}.site-filters{display:grid;grid-template-columns:repeat(4,1fr);width:100%;gap:2px}.site-filters button{padding:8px 5px;gap:5px;font-size:11px}.directory-caption{flex-direction:column;gap:5px}.site-card{padding:18px 15px}.site-card>header{gap:9px}.site-emblem{width:36px;height:36px}.site-card .badge{font-size:10px}.site-identity h2{font-size:15px}.site-metrics strong.rate{font-size:14px}.site-primary-actions{gap:5px}.site-primary-actions button{flex:1;font-size:11px;padding:8px 6px;gap:5px}.site-primary-actions .mount-action{flex:1.5;margin:0}.site-primary-actions .mount-action>svg:last-child{display:none}.site-meta{font-size:10px}}
</style>
